class OrderStatusManager:
    @staticmethod
    def set_status(order: Order, status: str):
        order.status = status

class CreditCardPaymentProcessor(PaymentProcessor):
    def pay(self, order, security_code: str):
        print('Processing credit card payment')
        print(f'Verifying security code: {security_code}')
        OrderStatusManager.set_status(order, 'paid')

class PaymentProcessorFactory:
    @staticmethod
    def create_processor(processor_type: str) -> PaymentProcessor:
        if processor_type == 'credit_card':
            return CreditCardPaymentProcessor()
        elif processor_type == 'debit_card':
            return DebitCardPaymentProcessor()
        elif processor_type == 'paypal':
            return PaypalPaymentProcessor()
        else:
            raise ValueError('Unknown processor type')
